package com.crypto.laplace.config;
import static org.assertj.core.api.Assertions.*;import com.crypto.laplace.model.StopReentryPolicy;import org.junit.jupiter.api.Test;
class LaplaceStrategyPropertiesTest {@Test void rejectsDualStrategy(){var p=new LaplaceStrategyProperties();p.setOldStrategyEnabled(true);assertThatThrownBy(p::validatePhaseOne).isInstanceOf(IllegalStateException.class);}@Test void acceptsImmutableDefaults(){var p=new LaplaceStrategyProperties();assertThatCode(p::validatePhaseOne).doesNotThrowAnyException();assertThat(p.getLaplace().getStopReentryPolicy()).isEqualTo(StopReentryPolicy.REQUIRE_OPPOSITE_SIGNAL);}}
